"""Validate candidate topology closure, voltage observability, and KG freeze."""
from collections import Counter
from common import *
def main():
 g=graph();c=read(WORK/'candidate_connections.json');n=read(WORK/'candidate_nets.json');cov=read(WORK/'port_coverage.json');role=read(WORK/'product_role_map.json');active={x['port_id']:x for x in active_ports(g)};cands=c['candidates'];nets={x['net_id']:x for x in n['nets']}
 hard=sum(1 for x in cands if not all(x['hard_checks'].values()));bad_end=sum(1 for x in cands if x['source_port_id'] not in active or (x['target_port_id'] and x['target_port_id'] not in active));dupcov=len(cov['coverage'])-len({x['port_id'] for x in cov['coverage']});missing=set(active)-{x['port_id'] for x in cov['coverage']};all_net_ports=[m['port_id'] for x in nets.values() for m in x['members']];net_bad=sum(1 for x in nets.values() for m in x['members'] if m['port_id'] not in active or active[m['port_id']]['item_code']!=x['item_code']);dc=nets['NET-DC-LINK-01'];dc_codes={x['product_code'] for x in dc['members']};modes=Counter(x['connection_mode'] for x in cands);dc_pair_candidates=sum(1 for x in cands if x['item_code']=='ITM-PHY-003' and x['target_port_id']);cross_storage=sum(1 for x in cands if x['target_port_id'] and {active[x['source_port_id']]['item_code'],active[x['target_port_id']]['item_code']}=={'ITM-PHY-003','ITM-PHY-016'});mechanical_shortcuts=sum(1 for x in cands if x['connection_mode']=='SERIES' and x['source_product']=='5311' and x['target_product'] in {'3111','3112','3121'});sensor_in_series=sum(1 for x in cands if x['connection_mode']=='SERIES' and ('SENSOR_TAP' in {x['source_role'],x['target_role']}) )
 def has(a,b,item=None):return any({x['source_product'],x['target_product']}=={a,b} and (not item or x['item_code']==item) for x in cands if x['target_product'])
