  {'name':'制动电阻耗散路径','status':'PASS' if '5142' in dc_codes and any(x['source_product']=='5142' and x['connection_mode']=='BOUNDARY' for x in cands) else 'FAIL','missing':'none'},
  {'name':'服务制动控制路径','status':'WARNING','missing':'部分Command存在多源或I/O部署歧义，保留UNRESOLVED而未直接驱动气动设备。'},
  {'name':'ATP/紧急制动路径','status':'WARNING','missing':'E100/8127/安全逻辑的I/O部署与命令仲裁存在UNRESOLVED_ROUTE。'},
