 voltage_status='PASS' if all(x['ok'] for x in voltage.values()) else 'VOLTAGE_CHAIN_INCOMPLETE';checks={'kg_v1_frozen':freeze_snapshot()['Active_EXPOSES']==511 and freeze_snapshot()['kg_sha256']==role['meta']['kg_sha256'],'coverage_exactly_once':len(cov['coverage'])==511 and not dupcov and not missing,'candidate_endpoints_active':bad_end==0,'hard_rule_violations_zero':hard==0,'net_member_violations_zero':net_bad==0,'unique_net_membership':len(all_net_ports)==len(set(all_net_ports)),'dc_link_not_clique':not dc['pairwise_clique_generated'] and dc_pair_candidates==0,'dc_storage_domains_separated':cross_storage==0,'no_motor_mechanical_shortcuts':mechanical_shortcuts==0,'sensor_taps_not_series':sensor_in_series==0,'no_final_CONNECTS_TO':not c['forbidden_output_created']}
 result={'summary':freeze_snapshot()|{'interface_compatible_raw_candidates':c['meta']['interface_compatible_raw_candidates'],'hard_rule_candidates':len(cands),'candidate_modes':dict(modes),'net_count':len(nets),'net_member_count':sum(len(x['members']) for x in nets.values()),'variant_conflicts':sum(x['status']=='UNRESOLVED_VARIANT' for x in variants()['variant_groups']),'unresolved_routes':len(c['unresolved_routes']),'coverage_counts':cov['meta']['coverage_counts'],'hard_rule_violations':hard},'checks':checks,'global_closure_qa':closure,'voltage_continuity':{'status':voltage_status,'observations':voltage},'overall':'PASS' if all(checks.values()) and voltage_status=='PASS' and not any(x['status']=='FAIL' for x in closure) else 'FAIL'};write(WORK/'topology_qa.json',result)
 # Reports are generated only from reread artifacts/results.
 route_lines=''.join(f"- `{x['target_port_id']}` / {x['item_code']}: {x['reason']}\n" for x in c['unresolved_routes']);issue_lines=''.join(f"- {x['type']} `{x['target_port_id']}`: {', '.join(x['source_products'])}\n" for x in c['issues'])
 (REPORTS/'candidate_connection_report.md').write_text('# Candidate Connection Report\n\n'+f"- Interface-compatible raw candidates: {result['summary']['interface_compatible_raw_candidates']}\n- Hard-rule candidates: {len(cands)}\n"+''.join(f"- {k}: {v}\n" for k,v in sorted(modes.items()))+f"- Candidate nets: {len(nets)}\n- Net members: {result['summary']['net_member_count']}\n- Variant conflicts: {result['summary']['variant_conflicts']}\n- UNRESOLVED_ROUTE: {result['summary']['unresolved_routes']}\n- Hard-rule violations: {hard}\n- Final CONNECTS_TO created: no\n\n## UNRESOLVED_ROUTE\n\n"+route_lines+'\n## Command cardinality unresolved\n\n'+issue_lines,encoding='utf-8')
 clines=['# Port Coverage Report','',f"- total_active_ports: {len(cov['coverage'])}"]+[f"- {k.lower()}: {v}" for k,v in sorted(cov['meta']['coverage_counts'].items())]+['',f"## UNRESOLVED ({len(cov['unresolved'])})",'']+[f"- `{x['port_id']}` — {x['reason']}" for x in cov['unresolved']];(REPORTS/'port_coverage_report.md').write_text('\n'.join(clines)+'\n',encoding='utf-8')
 qlines=['# Topology QA Report','',f"- Overall: {result['overall']}",f"- Voltage Continuity: {voltage_status}",f"- Hard-rule violations: {hard}",'','## 12 Global Closure Checks','']+[f"- {x['name']}: **{x['status']}** — {x['missing']}" for x in closure]+['','## Voltage observation locations','']+[f"- {k}: {'PASS' if v['ok'] else 'FAIL'} — {v['location']}" for k,v in voltage.items()]+['','## Structural checks','']+[f"- {k}: {'PASS' if v else 'FAIL'}" for k,v in checks.items()];(REPORTS/'topology_qa_report.md').write_text('\n'.join(qlines)+'\n',encoding='utf-8');print(json.dumps(result,ensure_ascii=False))
 if result['overall']!='PASS':raise SystemExit(1)
